// PLAN:
// 1. COMPOSITION: primary gear (1.6u) centered at origin, secondary gear (0.9u) at [1.15,0.35,-0.1], jewel pivot sphere at primary hub, arbor shafts through both hubs, contact-shadow ellipse at y=-1.2, 7x6 gradient backdrop at z=-3, headline y=-1.7 / caption y=-2.1.
// 2. LIGHT RIG: rig-ember-glow — warm key point #ffb37a i9 [1.8,0.7,1.9], fill point #c9924f i3 [-2.2,0.4,1.2], rim directional #fff0dc i1.2 from [-0.8,2.6,-2.4], ambient floor 0.07 node-local.
// 3. MATERIALS: machined steel PBR (rough 0.5, metal 0.55, clearcoat 0.2), ink arbors, transmissive emissive #ff2a38 jewel (the ONE brightest element), TSL vertical gradient backdrop.
// 4. MOTION: phase-locked meshing rotation (primary 0.08 rad/s, secondary -0.142 rad/s), weighted-settle entrance 1.04->1.0 power4.out, orbit primitive (time, speed 0.08, radius 0.2).
// 5. FOCAL: the red jewel pivot at the primary gear hub — emissive 1.8, everything else graded below it.

import { MeshStandardNodeMaterial, MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, float, sub, length, oneMinus } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, CircleGeometry, SphereGeometry, CylinderGeometry, PointLight, DirectionalLight, AmbientLight, Color, Box3, Vector3 } = ctx.THREE;

  const COLORS = (config.intent && config.intent.visualSpec && config.intent.visualSpec.colors) || {};
  const BG = COLORS.background || '#0b0b10';
  const SURFACE = COLORS.surface || '#14141a';
  const INK = COLORS.ink || '#16161d';
  const PAPER = COLORS.paper || '#e8ecf2';
  const ACCENT = COLORS.accent || '#ff2a38';

  const group = new Group();
  const disposables = [];
  const timelines = [];
  const primitiveHandles = [];

  // ---- backdropStage: 7x6 gradient plane at z=-3 (gradientStops 0/#0b0b10, 0.65/#101017, 1/#16161d) ----
  const bgGeo = new PlaneGeometry(7, 6);
  const bgMat = new MeshBasicNodeMaterial();
  const c0 = vec3(new Color(BG).toArray());
  const c1 = vec3(new Color('#101017').toArray());
  const c2 = vec3(new Color(INK).toArray());
  const v = uv().y;
  const lower = mix(c0, c1, smoothstep(float(0.0), float(0.65), v));
  const grad = mix(lower, c2, smoothstep(float(0.65), float(1.0), v));
  // subtle radial lift toward center so the stage never reads flat void
  const d = length(uv().sub(0.5));
  bgMat.colorNode = mix(grad.mul(float(1.15)), grad, smoothstep(float(0.1), float(0.6), d));
  const backdrop = new Mesh(bgGeo, bgMat);
  backdrop.position.set(0, 0, -3);
  group.add(backdrop);
  disposables.push(bgGeo, bgMat);

  // faint surface arc behind gears (architectural depth plane, surface tone)
  const arcGeo = new CircleGeometry(2.4, 64);
  const arcMat = new MeshStandardNodeMaterial({ color: new Color(SURFACE), roughness: 0.85, metalness: 0.2 });
  const arc = new Mesh(arcGeo, arcMat);
  arc.position.set(0.2, 0.1, -1.6);
  group.add(arc);
  disposables.push(arcGeo, arcMat);

  // ---- lightRig: rig-ember-glow ----
  const ambient = new AmbientLight(0xffffff, 0.07);
  const key = new PointLight(new Color('#ffb37a'), 9, 10, 2);
  key.position.set(1.8, 0.7, 1.9);
  const fill = new PointLight(new Color('#c9924f'), 3, 8, 2);
  fill.position.set(-2.2, 0.4, 1.2);
  const rim = new DirectionalLight(new Color('#fff0dc'), 1.2);
  rim.position.set(-0.8, 2.6, -2.4);
  rim.target.position.set(0, 0.5, 0);
  group.add(ambient, key, fill, rim, rim.target);

  // ---- gearMaterial: machined steel ----
  const steelMat = new MeshPhysicalNodeMaterial({
    color: new Color(SURFACE),
    roughness: 0.5,
    metalness: 0.55,
    clearcoat: 0.2,
    clearcoatRoughness: 0.3,
  });
  disposables.push(steelMat);

  // ---- gearAssembly: primary + secondary from GLB, phase-locked meshing ----
  const primaryPivot = new Group();
  const secondaryPivot = new Group();
  secondaryPivot.position.set(1.15, 0.35, -0.1);
  secondaryPivot.rotation.z = Math.PI / 16; // tooth phase offset so teeth never intersect (16:9)
  group.add(primaryPivot, secondaryPivot);

  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      const src = gltf.scene;
      src.traverse((o) => { if (o.isMesh) o.material = steelMat; });
      const box = new Box3().setFromObject(src);
      const size = new Vector3();
      box.getSize(size);
      const diam = Math.max(size.x, size.y) || 1;

      const primary = src;
      primary.scale.setScalar(1.6 / diam);
      primaryPivot.add(primary);

      const secondary = src.clone(true);
      secondary.scale.setScalar(0.9 / diam);
      secondaryPivot.add(secondary);

      // weighted-settle entrance
      const settle = gsap.timeline();
      primaryPivot.scale.setScalar(1.04);
      settle.to(primaryPivot.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' });
      settle.fromTo(group.position, { y: 0.25 }, { y: 0, duration: 0.7, ease: 'power3.out' }, 0);
      timelines.push(settle);
    });
  }

  // meshing rotation: primary 0.08 rad/s, secondary -0.142 rad/s (16:9 ratio)
  const spin = gsap.timeline({ repeat: -1 });
  const TWO_PI = Math.PI * 2;
  spin.to(primaryPivot.rotation, { z: `+=${TWO_PI}`, duration: TWO_PI / 0.08, ease: 'none' }, 0);
  spin.to(secondaryPivot.rotation, { z: `-=${TWO_PI * (0.142 / 0.08)}`, duration: TWO_PI / 0.08, ease: 'none' }, 0);
  timelines.push(spin);

  // ---- jewelPivot: FOCAL — red transmissive emissive sphere at primary hub ----
  const jewelGeo = new SphereGeometry(0.12, 32, 32);
  const jewelMat = new MeshPhysicalNodeMaterial({
    color: new Color(ACCENT),
    transmission: 0.6,
    ior: 1.76,
    thickness: 0.12,
    roughness: 0.15,
    metalness: 0,
    emissive: new Color(ACCENT),
    emissiveIntensity: 1.8,
  });
  const jewel = new Mesh(jewelGeo, jewelMat);
  jewel.position.set(0, 0, 0.15);
  group.add(jewel);
  disposables.push(jewelGeo, jewelMat);

  // ---- arborShafts: ink cylinders through both hubs ----
  const arborGeo = new CylinderGeometry(0.05, 0.05, 0.8, 24);
  const arborMat = new MeshStandardNodeMaterial({ color: new Color(INK), roughness: 0.6, metalness: 0.4 });
  const arborA = new Mesh(arborGeo, arborMat);
  arborA.rotation.x = Math.PI / 2;
  arborA.position.set(0, 0, 0);
  const arborB = new Mesh(arborGeo, arborMat);
  arborB.rotation.x = Math.PI / 2;
  arborB.position.set(1.15, 0.35, -0.1);
  group.add(arborA, arborB);
  disposables.push(arborGeo, arborMat);

  // ---- contactShadow: radial ellipse 2.6 x 1.2 at y=-1.2, opacity 0.5 ----
  const shGeo = new CircleGeometry(1, 48);
  const shMat = new MeshBasicNodeMaterial({ transparent: true });
  const sd = length(uv().sub(0.5).mul(2.0));
  shMat.colorNode = vec3(0, 0, 0);
  shMat.opacityNode = oneMinus(smoothstep(float(0.2), float(1.0), sd)).mul(float(0.5));
  const shadow = new Mesh(shGeo, shMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.scale.set(1.3, 0.6, 1);
  shadow.position.set(0.4, -1.2, 0);
  group.add(shadow);
  disposables.push(shGeo, shMat);

  // ---- textBlock: headline + caption via fontAtlas, verbatim spec copy ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find((i) => i.role === 'headline') || { text: 'The going train' };
  const captionItem = items.find((i) => i.role === 'caption') || { text: '34 COMPONENTS / HAND-FINISHED' };

  const headline = ctx.fontAtlas.createText(headlineItem.text, {
    fontSize: headlineItem.typography?.fontSize ?? 68,
    color: PAPER,
    align: 'center',
  });
  headline.position.set(0, -1.7, 0.4);
  group.add(headline);

  const caption = ctx.fontAtlas.createText(captionItem.text, {
    fontSize: captionItem.typography?.fontSize ?? 18,
    color: PAPER,
    align: 'center',
    letterSpacingPx: 1.5,
  });
  caption.position.set(0, -2.1, 0.4);
  group.add(caption);

  // text fade-up entrance
  const textIn = gsap.timeline();
  textIn.fromTo(headline.position, { y: -1.9 }, { y: -1.7, duration: 0.7, ease: 'power3.out' }, 0.15);
  textIn.fromTo(caption.position, { y: -2.3 }, { y: -2.1, duration: 0.7, ease: 'power3.out' }, 0.3);
  timelines.push(textIn);

  // ---- applyPrimitives: every config.cinematicPrimitives via ctx.primitives ----
  for (const prim of config.cinematicPrimitives ?? []) {
    if (ctx.primitives[prim.name]) {
      primitiveHandles.push(ctx.primitives[prim.name](group, prim.params));
    }
  }

  group.userData.handlers = {};
  group.userData.cleanup = () => {
    for (const tl of timelines) tl.kill();
    for (const h of primitiveHandles) h?.cleanup?.();
    for (const r of disposables) r?.dispose?.();
    group.traverse((o) => {
      if (o.isMesh) {
        o.geometry?.dispose?.();
        if (o.material && !disposables.includes(o.material)) o.material.dispose?.();
      }
    });
  };

  return group;
}

/* @spec-manifest
{"elements":[
{"id":"text.headline.0","where":"textBlock","how":"fontAtlas headline at y=-1.7"},
{"id":"text.caption.1","where":"textBlock","how":"fontAtlas caption at y=-2.1"},
{"id":"color.background","where":"backdropStage","how":"gradient stop 0 on backdrop"},
{"id":"color.surface","where":"gearMaterial","how":"steel base color and arc plane"},
{"id":"color.ink","where":"arborShafts","how":"arbor cylinders and gradient stop 1"},
{"id":"color.paper","where":"textBlock","how":"headline and caption text color"},
{"id":"color.accent","where":"jewelPivot","how":"jewel color emissive transmission"},
{"id":"color.gradient","where":"backdropStage","how":"3-stop TSL vertical gradient"},
{"id":"effects.spec","where":"gearAssembly","how":"GLB gears, meshing spin, PBR, shadow, fog-toned stage"},
{"id":"primitive.orbit","where":"applyPrimitives","how":"ctx.primitives orbit on group"}
]}
*/
